import re
from rich.ansi import _AnsiToken

# Original regex
re_ansi_orig = re.compile(r'(?:\\x1b\\](.*?)\\x1b\\\\)|(?:\\x1b([(@-Z\\\\-_]|\\[[0-?]*[ -/]*[@-~])))')

def _ansi_tokenize_orig(ansi_text):
    position = 0
    for match in re_ansi_orig.finditer(ansi_text):
        start, end = match.span(0)
        osc, sgr = match.groups()
        if start > position:
            yield _AnsiToken(ansi_text[position:start])
        if sgr:
            if sgr == "(":
                position = end + 1
                continue
            if sgr.endswith("m"):
                yield _AnsiToken("", sgr[1:-1], osc)
        else:
            yield _AnsiToken("", sgr, osc)
        position = end
    if position < len(ansi_text):
        yield _AnsiToken(ansi_text[position:])

# Modified regex
re_ansi_mod = re.compile(r'(?:\\x1b\\](.*?)\\x1b\\\\)|(?:\\x1b([(0-Z\\\\-_]|\\[[0-?]*[ -/]*[@-~])))')

def _ansi_tokenize_mod(ansi_text):
    position = 0
    for match in re_ansi_mod.finditer(ansi_text):
        start, end = match.span(0)
        osc, sgr = match.groups()
        if start > position:
            yield _AnsiToken(ansi_text[position:start])
        if sgr:
            if sgr == "(":
                position = end + 1
                continue
            if sgr.endswith("m"):
                yield _AnsiToken("", sgr[1:-1], osc)
        else:
            yield _AnsiToken("", sgr, osc)
        position = end
    if position < len(ansi_text):
        yield _AnsiToken(ansi_text[position:])

print(f"Original: {list(_ansi_tokenize_orig('\x1b7'))}")
print(f"Modified: {list(_ansi_tokenize_mod('\x1b7'))}")
